import{_ as i,o as t,c as a,a2 as o}from"./chunks/framework.BFzNpupd.js";const p=JSON.parse('{"title":"Maintenance & Bug Fixing","description":"","frontmatter":{},"headers":[],"relativePath":"standards/03_MAINTENANCE_AND_BUG_FIXING.md","filePath":"standards/03_MAINTENANCE_AND_BUG_FIXING.md"}'),n={name:"standards/03_MAINTENANCE_AND_BUG_FIXING.md"};function s(r,e,l,c,d,g){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="maintenance-bug-fixing" tabindex="-1">Maintenance &amp; Bug Fixing <a class="header-anchor" href="#maintenance-bug-fixing" aria-label="Permalink to &quot;Maintenance &amp; Bug Fixing&quot;">​</a></h1><p>Guidelines for triaging, debugging, and resolving production issues (Bugs, ANRs, Regressions) safely.</p><h2 id="_1-bug-fixing-protocol-ai-developer-workflow" tabindex="-1">1. Bug Fixing Protocol (AI &amp; Developer Workflow) <a class="header-anchor" href="#_1-bug-fixing-protocol-ai-developer-workflow" aria-label="Permalink to &quot;1. Bug Fixing Protocol (AI &amp; Developer Workflow)&quot;">​</a></h2><p>When implementing a fix or addressing an issue, strict adherence to the following sequence is mandatory. <strong>Do not make any assumptions, fail out loud, and ask for clarity.</strong></p><ol><li><strong>Information Gathering:</strong> Completely gather all necessary data before touching code. Ask the user for crash logs, system traces, or screenshots if they are required. The user can provide system traces for code if needed.</li><li><strong>Analysis:</strong> Analyze the codebase deeply and identify the accurate, root-cause fix.</li><li><strong>Preview (Diff Style):</strong> Propose the change to the user using a <code>diff</code> style format (or via an <code>implementation_plan.md</code> artifact). Clearly state the class name and function being modified.</li><li><strong>Approval &amp; Execution:</strong> Do not apply corrections until explicit approval is given by the user. Once approved, apply the exact changes.</li><li><strong>Post-Correction Review:</strong> After applying the fix, show the resulting code changes using a <code>diff</code> style summary to confirm the exact modifications made.</li><li><strong>Verification:</strong> Ask the user to check the fix on a physical device. Only mark the task as completed after on-device verification is successful.</li></ol><h2 id="_2-triage-investigation" tabindex="-1">2. Triage &amp; Investigation <a class="header-anchor" href="#_2-triage-investigation" aria-label="Permalink to &quot;2. Triage &amp; Investigation&quot;">​</a></h2><ul><li><strong>Trace the Source:</strong> When presented with a stack trace (e.g., from Firebase Crashlytics), isolate the specific layer. Is it a UI crash? A background service exception? A location permission denial?</li><li><strong>Avoid Guesswork:</strong> Do not blindly wrap code in <code>try/catch</code>. Find the root cause (e.g., <code>NullPointerException</code> because GPS returned null before lock-on).</li></ul><h2 id="_2-fixing-application-not-responding-anrs" tabindex="-1">2. Fixing Application Not Responding (ANRs) <a class="header-anchor" href="#_2-fixing-application-not-responding-anrs" aria-label="Permalink to &quot;2. Fixing Application Not Responding (ANRs)&quot;">​</a></h2><p>ANRs occur when the Main (UI) thread is blocked for &gt; 5 seconds.</p><ul><li><strong>Rule:</strong> Never perform I/O, database reads (Room/DataStore), or heavy computation (like filtering GPS arrays) on the Main thread.</li><li><strong>Fix:</strong> Move heavy work to <code>Dispatchers.IO</code> or <code>Dispatchers.Default</code> using Coroutines.<div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Dispatchers.Default) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // heavy GPS math</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li></ul><h2 id="_3-the-regression-testing-rule" tabindex="-1">3. The Regression Testing Rule <a class="header-anchor" href="#_3-the-regression-testing-rule" aria-label="Permalink to &quot;3. The Regression Testing Rule&quot;">​</a></h2><p>Before fixing any reported bug, <strong>you must write a failing test</strong> that reproduces the bug.</p><ol><li>Write a Unit Test that mimics the conditions of the crash. It should fail.</li><li>Implement the fix in the codebase.</li><li>Run the test again. It should pass. This ensures the bug is caught in CI/CD and never returns.</li></ol><h2 id="_4-safe-refactoring" tabindex="-1">4. Safe Refactoring <a class="header-anchor" href="#_4-safe-refactoring" aria-label="Permalink to &quot;4. Safe Refactoring&quot;">​</a></h2><p>When modernizing legacy code (e.g., migrating an old XML Activity to Compose or refactoring the <code>SpeedometerService</code>):</p><ul><li><strong>Isolate:</strong> Extract the business logic from the Android component into a decoupled class first.</li><li><strong>Test:</strong> Write tests for the decoupled logic.</li><li><strong>Replace:</strong> Swap the old implementation for the new one. Ensure zero functional changes from the user&#39;s perspective unless explicitly requested.</li></ul>`,16)])])}const u=i(n,[["render",s]]);export{p as __pageData,u as default};
